export const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const unpinned=v=>v===null?'not yet quantified':e(v);
export function memberCard(m,progress,{editable=false}={}){
 const hp=m.resources[0];const action=(name,label,extra='')=>editable?`<button data-action="${name}" data-member="${e(m.roster_id)}" ${extra}>${label}</button>`:'';
 return `<section class="card roster-member"><div class="section-head"><div><p class="eyebrow">${e(m.species)} · ${e(m.status)}</p><h2>${e(m.nickname||m.species)}</h2></div>${action('roster-edit','Edit')}</div><div class="stats-row"><div><span>Level</span><strong class="stat-value">${m.level}</strong></div><div><span>XP</span><strong class="stat-value">${m.xp_total}</strong><p class="small muted">${progress.status==='known'?progress.remaining+' to next level':'Next level threshold '+progress.status}</p></div></div><div class="resource"><span>HP</span><div class="big-number">${hp.current} <span>/ ${hp.max}</span></div>${hp.current>hp.max?'<p class="over-max">Current exceeds maximum</p>':''}<progress max="${Math.max(1,hp.max)}" value="${Math.min(hp.max,Math.max(0,hp.current))}" aria-label="HP"></progress><div class="actions">${action('roster-hp','Adjust HP')}</div></div><div class="ref-grid">${m.stats.map(s=>`<div class="attribute"><span>${e(s.label)}</span><strong>${s.value}</strong></div>`).join('')}</div><dl class="roster-facts"><dt>Ability · confirmed at catch</dt><dd>${e(m.ability)}</dd><dt>Bond</dt><dd>${e(m.bond)}</dd><dt>Held item</dt><dd>${m.held_item===null?'None':e(m.held_item)}</dd><dt>Status condition</dt><dd>${m.status_condition?e(m.status_condition.name)+' · '+(m.status_condition.duration_remaining===null?'duration not yet quantified':m.status_condition.duration_remaining+' '+e(m.status_condition.duration_unit)):'None'}</dd></dl><h3>Moves</h3>${m.moves.length?m.moves.map(move=>`<details class="ability"><summary><span class="ability-name">${e(move.name)}</span><span>${e(move.type)} · ${e(move.category)}</span><strong>PP ${move.pp_current} / ${move.pp_max}${move.pp_current>move.pp_max?' · above maximum':''}</strong></summary><dl><dt>Power</dt><dd>${unpinned(move.power)}</dd><dt>Accuracy</dt><dd>${unpinned(move.accuracy)}</dd><dt>Effect</dt><dd>${e(move.effect)}</dd></dl><div class="actions">${action('roster-pp','Adjust PP',`data-move="${e(move.move_id)}"`)}${action('roster-move','Edit move',`data-move="${e(move.move_id)}"`)}</div></details>`).join(''):'<p class="muted">No moves recorded.</p>'}<div class="actions">${action('roster-move','Add move')}${action('roster-box',m.status==='active'?'Move to box':'Make active')}</div></section>`;
}
